            raise TypeError("tag.stage must be an integer")
        if not 0 <= tag.stage < _MAX_STAGE:
            raise ValueError("tag.stage must satisfy 0 <= stage < 2**64")
        if not isinstance(tag.tag, bytes):
            raise TypeError("tag.tag must be bytes")
